def move_content_types(apps, schema_editor):
    """
    Keep existing content types and permissions (and their group/user grants) by moving them to the core
    app instead of letting post_migrate create new empty ones. If the core content type already exists
    (post_migrate ran between companies.0005 and this migration), the grants are copied onto the matching
    core permissions instead. Nothing is deleted.
    """
    ContentType = apps.get_model('contenttypes', 'ContentType')
    Permission = apps.get_model('auth', 'Permission')
    GroupPerm = apps.get_model('auth', 'Group').permissions.through
    UserPerm = apps.get_model(settings.AUTH_USER_MODEL).user_permissions.through
    for old, new in RENAMES:
        ct = ContentType.objects.filter(app_label='personnel', model=old).first()
        if ct is None:
            continue
        new_ct = ContentType.objects.filter(app_label='companies', model=new).first()
        if new_ct is None:
            ct.app_label, ct.model = 'companies', new
            ct.save(update_fields=['app_label', 'model'])
            if old != new:
                for perm in Permission.objects.filter(content_type=ct, codename__endswith='_' + old):
                    perm.codename = perm.codename[: -len(old)] + new
                    perm.save(update_fields=['codename'])
            continue
        for perm in Permission.objects.filter(content_type=ct, codename__endswith='_' + old):
            target = Permission.objects.filter(
                content_type=new_ct, codename=perm.codename[: -len(old)] + new
            ).first()
            if target is None:
                continue
            for row in GroupPerm.objects.filter(permission_id=perm.id):
                GroupPerm.objects.get_or_create(group_id=row.group_id, permission_id=target.id)
            for row in UserPerm.objects.filter(permission_id=perm.id):
                UserPerm.objects.get_or_create(**{
                    f.attname: getattr(row, f.attname)
                    for f in UserPerm._meta.concrete_fields if f.attname not in ('id', 'permission_id')
                }, permission_id=target.id)


